<svelte:head><title>{data.view==='login'?'Anmelden':data.view==='setup'?'Einrichtung':data.module?.label||({dashboard:'Heute',time:'Meine Zeit',studio:'Planungsstudio',reports:'Auswertungen',help:'Hilfe & Einführung',settings:'Betrieb & Verwaltung',portal:'Ihr Projektbereich',withdrawal:'Widerruf übermitteln'} as Record<string,string>)[data.view]||'Arbeitsbereich'} · SCHUBERT</title><meta name="description" content="Der gemeinsame Arbeitsbereich für Schubert: Beratung, Planung, Büro, Werkstatt und Baustelle."/><meta name="theme-color" content="#315c4c"/><meta name="robots" content="noindex,nofollow"/><link rel="manifest" href="/manifest.webmanifest"/></svelte:head>
