nded={menuOpen} onclick={()=>menuOpen=!menuOpen}><Icon name="menu" size={21}/>Mehr</button>{#if data.summary?.feedback?.enabled&&data.user}<button aria-haspopup="dialog" data-feedback-private onclick={()=>window.dispatchEvent(new Event('schubert:feedback:open'))}><Icon name="pen" size={21}/>Feedback</button>{/if}</nav><div class="support-dock"><Assistant {data}/><FeedbackWidget {data}/></div>{#if permitted(data,'account.self')&&!['completed','deferred'].includes(data.summary?.onboarding?.status)}<Onboarding {data}/>{/if}</div>{/if}
{#if logoutPending}<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="logout-title" tabindex="-1" use:focusTrap><header class="modal-header"><div><h2 id="logout-title">Zeiten noch nicht übertragen</h2><p>{unsent} Aufzeichnung(en) warten auf Bestätigung.</p></div></header><div class="modal-body"><p>Die lokalen Zeiten bleiben Ihrem persönlichen Zugang zugeordnet und werden beim Abmelden nicht gelöscht. Melden Sie sich zum Übertragen wieder mit demselben Konto an.</p></div><footer class="modal-footer"><button class="btn" onclick={()=>logoutPending=false}>Zurück</button><a class="btn primary" href="/time" onclick={()=>logoutPending=false}>Jetzt synchronisieren</a><button class="btn" onclick={()=>logout(true)} disabled={loggingOut}>Abmelden & lokal behalten</button></footer></div></div>{/if}
